@implementation SLSyncService
+ (NSString *)token:(NSString *)raw { NSString *t=[raw stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];if([t hasPrefix:@"Bearer "]||[t hasPrefix:@"bearer "])t=[t substringFromIndex:7];return [t stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]]; }
+ (void)request:(NSString *)method url:(NSString *)url token:(NSString *)token body:(NSDictionary *)body completion:(void (^)(id,NSError *,NSInteger))completion {
    NSMutableURLRequest *r=[NSMutableURLRequest requestWithURL:[NSURL URLWithString:url] cachePolicy:NSURLRequestReloadIgnoringLocalCacheData timeoutInterval:35];[r setHTTPMethod:method];[r setValue:[NSString stringWithFormat:@"token %@",token] forHTTPHeaderField:@"Authorization"];[r setValue:@"application/vnd.github+json" forHTTPHeaderField:@"Accept"];[r setValue:@"application/json" forHTTPHeaderField:@"Content-Type"];if(body)[r setHTTPBody:[NSJSONSerialization dataWithJSONObject:body options:0 error:nil]];
    [NSURLConnection sendAsynchronousRequest:r queue:[[[NSOperationQueue alloc]init]autorelease] completionHandler:^(NSURLResponse *response,NSData *data,NSError *error){NSInteger status=[(NSHTTPURLResponse *)response statusCode];id obj=data?[NSJSONSerialization JSONObjectWithData:data options:NSJSONReadingMutableContainers error:nil]:nil;NSError *out=error;if(!out&&status>=400)out=[NSError errorWithDomain:@"SlashlibSync" code:status userInfo:[NSDictionary dictionaryWithObject:(status==401?@"GitHub token недействителен": [NSString stringWithFormat:@"GitHub HTTP %ld",(long)status]) forKey:NSLocalizedDescriptionKey]];dispatch_async(dispatch_get_main_queue(),^{if(completion)completion(obj,out,status);});}];
}
+ (NSDictionary *)localDocument { return [NSDictionary dictionaryWithObjectsAndKeys:[NSNumber numberWithInt:1],@"version",[NSNumber numberWithDouble:[[NSDate date]timeIntervalSince1970]],@"updated",[SLStore array:@"SLBookmarks"],@"bookmarks",[SLStore array:@"SLFavorites"],@"favorites",[SLStore array:@"SLHistory"],@"recent",[[NSUserDefaults standardUserDefaults]objectForKey:@"SLRead"]?:[NSDictionary dictionary],@"read",[[NSUserDefaults standardUserDefaults]objectForKey:@"SLTombstones"]?:[NSDictionary dictionary],@"tombstones",nil]; }
+ (NSString *)stableKey:(NSDictionary *)d kind:(NSString *)kind { NSDictionary *ref=[d objectForKey:@"ref"];NSString *slug=[[[d objectForKey:@"slug"] description] length]?[[d objectForKey:@"slug"]description]:[[d objectForKey:@"slug_url"]description];if(![slug length]&&[ref isKindOfClass:[NSDictionary class]])slug=[[ref objectForKey:@"slug"]description];if([kind isEqualToString:@"favorite"]||[kind isEqualToString:@"recent"])return slug?:@"";return [NSString stringWithFormat:@"%@#%@",slug?:@"",[d objectForKey:@"chapterId"]?:[d objectForKey:@"id"]?:@"0"]; }
+ (double)dateStamp:(id)v {if([v respondsToSelector:@selector(doubleValue)]&&![v isKindOfClass:[NSString class]])return [v doubleValue];if([v isKindOfClass:[NSString class]]){NSArray *formats=[NSArray arrayWithObjects:@"yyyy-MM-dd'T'HH:mm:ss.SSSZ",@"yyyy-MM-dd'T'HH:mm:ssZ",@"yyyy-MM-dd'T'HH:mm:ss.SSS'Z'",@"yyyy-MM-dd'T'HH:mm:ss'Z'",nil];for(NSString *format in formats){NSDateFormatter *f=[[[NSDateFormatter alloc]init]autorelease];[f setLocale:[[[NSLocale alloc]initWithLocaleIdentifier:@"en_US_POSIX"]autorelease]];[f setTimeZone:[NSTimeZone timeZoneForSecondsFromGMT:0]];[f setDateFormat:format];NSDate *date=[f dateFromString:v];if(date)return [date timeIntervalSince1970];}}return 0;}
+ (double)stamp:(NSDictionary *)d { return [self dateStamp:[d objectForKey:@"_date"]?:[d objectForKey:@"date"]]; }
+ (NSString *)isoDate:(double)stamp {NSDate *date=[NSDate dateWithTimeIntervalSince1970:stamp>0?stamp:[[NSDate date]timeIntervalSince1970]];NSDateFormatter *f=[[[NSDateFormatter alloc]init]autorelease];[f setLocale:[[[NSLocale alloc]initWithLocaleIdentifier:@"en_US_POSIX"]autorelease]];[f setTimeZone:[NSTimeZone timeZoneForSecondsFromGMT:0]];[f setDateFormat:@"yyyy-MM-dd'T'HH:mm:ss'Z'"];return [f stringFromDate:date];}
+ (NSNumber *)intNumber:(id)value {if([value respondsToSelector:@selector(integerValue)])return [NSNumber numberWithInteger:[value integerValue]];return [NSNumber numberWithInt:0];}
+ (NSString *)coverString:(id)cover {if([cover isKindOfClass:[NSString class]])return cover;if([cover isKindOfClass:[NSDictionary class]])return [cover objectForKey:@"thumbnail"]?:[cover objectForKey:@"default"]?:[cover objectForKey:@"full"];return nil;}
+ (NSDictionary *)coverObject:(id)cover {NSString *url=[self coverString:cover];return [url length]?[NSDictionary dictionaryWithObjectsAndKeys:url,@"thumbnail",url,@"default",nil]:nil;}
+ (NSDictionary *)normalizedFavorite:(NSDictionary *)raw {if(![raw objectForKey:@"ref"])return raw;NSDictionary *ref=[raw objectForKey:@"ref"];NSString *slug=[ref objectForKey:@"slug"]?:@"";NSMutableDictionary *d=[NSMutableDictionary dictionaryWithObjectsAndKeys:slug,@"slug",slug,@"slug_url",[ref objectForKey:@"name"]?:slug,@"rus_name",nil];NSDictionary *cover=[self coverObject:[ref objectForKey:@"cover"]];if(cover)[d setObject:cover forKey:@"cover"];if([ref objectForKey:@"site"])[d setObject:[ref objectForKey:@"site"] forKey:@"site"];[d setObject:[NSNumber numberWithDouble:[self dateStamp:[raw objectForKey:@"date"]]] forKey:@"_date"];return d;}
+ (NSDictionary *)normalizedBookmark:(NSDictionary *)raw recent:(BOOL)recent {if(recent&&[raw objectForKey:@"_lastChapter"])return raw;if(!recent&&[raw objectForKey:@"titleInfo"])return raw;NSString *slug=[raw objectForKey:@"slug"]?:@"";NSString *title=[raw objectForKey:@"titleName"]?:slug;NSMutableDictionary *titleInfo=[NSMutableDictionary dictionaryWithObjectsAndKeys:slug,@"slug",slug,@"slug_url",title,@"rus_name",nil];NSDictionary *cover=[self coverObject:[raw objectForKey:@"cover"]];if(cover)[titleInfo setObject:cover forKey:@"cover"];if([raw objectForKey:@"site"])[titleInfo setObject:[raw objectForKey:@"site"] forKey:@"site"];NSMutableDictionary *chapter=[NSMutableDictionary dictionaryWithObjectsAndKeys:[raw objectForKey:@"chapterId"]?:@0,@"id",[raw objectForKey:@"volume"]?:@"0",@"volume",[raw objectForKey:@"number"]?:@"0",@"number",[raw objectForKey:@"chapterName"]?:@"",@"name",[raw objectForKey:@"branchIds"]?:[NSArray array],@"branchIds",nil];if([raw objectForKey:@"site"])[chapter setObject:[raw objectForKey:@"site"] forKey:@"site"];NSMutableDictionary *out=[NSMutableDictionary dictionaryWithObjectsAndKeys:slug,@"slug",[raw objectForKey:@"chapterId"]?:@0,@"chapterId",[raw objectForKey:@"volume"]?:@"0",@"volume",[raw objectForKey:@"number"]?:@"0",@"number",[raw objectForKey:@"page"]?:@0,@"page",[raw objectForKey:@"pageCount"]?:@0,@"pageCount",[NSNumber numberWithDouble:[self dateStamp:[raw objectForKey:@"date"]]],@"date",titleInfo,@"titleInfo",[raw objectForKey:@"chapterName"]?:@"",@"chapterName",[raw objectForKey:@"branchIds"]?:[NSArray array],@"branchIds",chapter,@"chapter",nil];if(recent){[out setObject:titleInfo forKey:@"titleInfo"];[out setObject:chapter forKey:@"_lastChapter"];[out setObject:[raw objectForKey:@"page"]?:@0 forKey:@"_lastPage"];[out setObject:[raw objectForKey:@"pageCount"]?:@0 forKey:@"_pageCount"];[out setObject:[NSNumber numberWithDouble:[self dateStamp:[raw objectForKey:@"date"]]] forKey:@"_date"];[out setObject:slug forKey:@"slug_url"];[out setObject:slug forKey:@"slug"];[out setObject:title forKey:@"rus_name"];if(cover)[out setObject:cover forKey:@"cover"];if([raw objectForKey:@"site"])[out setObject:[raw objectForKey:@"site"] forKey:@"site"];}else{[out setObject:[NSNumber numberWithDouble:[self dateStamp:[raw objectForKey:@"date"]]] forKey:@"date"];}return out;}
+ (NSDictionary *)normalizeDocument:(NSDictionary *)doc {if(![doc isKindOfClass:[NSDictionary class]])return [NSDictionary dictionary];NSMutableDictionary *out=[NSMutableDictionary dictionaryWithDictionary:doc];NSMutableArray *fav=[NSMutableArray array];for(NSDictionary *x in [doc objectForKey:@"favorites"]?:[NSArray array])[fav addObject:[self normalizedFavorite:x]];[out setObject:fav forKey:@"favorites"];NSMutableArray *bm=[NSMutableArray array];for(NSDictionary *x in [doc objectForKey:@"bookmarks"]?:[NSArray array])[bm addObject:[self normalizedBookmark:x recent:NO]];[out setObject:bm forKey:@"bookmarks"];NSMutableArray *rec=[NSMutableArray array];for(NSDictionary *x in [doc objectForKey:@"recent"]?:[NSArray array])[rec addObject:[self normalizedBookmark:x recent:YES]];[out setObject:rec forKey:@"recent"];NSMutableDictionary *t=[NSMutableDictionary dictionary];NSDictionary *t0=[doc objectForKey:@"tombstones"];for(NSString *k in t0)[t setObject:[NSNumber numberWithDouble:[self dateStamp:[t0 objectForKey:k]]] forKey:k];[out setObject:t forKey:@"tombstones"];NSMutableDictionary *read=[NSMutableDictionary dictionary];NSDictionary *read0=[doc objectForKey:@"read"];for(NSString *slug in read0){NSMutableArray *ids=[NSMutableArray array];for(id value in [read0 objectForKey:slug])[ids addObject:[self intNumber:value]];[read setObject:ids forKey:slug];}[out setObject:read forKey:@"read"];return out;}
+ (NSDictionary *)canonicalBookmark:(NSDictionary *)raw recent:(BOOL)recent {NSDictionary *titleInfo=recent?raw:[raw objectForKey:@"titleInfo"];NSDictionary *ch=recent?[raw objectForKey:@"_lastChapter"]:([raw objectForKey:@"chapter"]?:raw);NSString *slug=[raw objectForKey:@"slug"]?:[raw objectForKey:@"slug_url"]?:@"";id chapterID=[self intNumber:[raw objectForKey:@"chapterId"]?:[ch objectForKey:@"id"]?:@0];id page=recent?([raw objectForKey:@"_lastPage"]?:@0):([raw objectForKey:@"page"]?:@0);id pageCount=recent?([raw objectForKey:@"_pageCount"]?:@0):([raw objectForKey:@"pageCount"]?:@0);id date=recent?([raw objectForKey:@"_date"]?:[raw objectForKey:@"date"]):[raw objectForKey:@"date"];NSMutableArray *branches=[NSMutableArray array];for(NSDictionary *b in [ch objectForKey:@"branches"]?:[NSArray array]){id bid=[b objectForKey:@"branch_id"];if(bid)[branches addObject:[self intNumber:bid]];}if(![branches count]&&[ch objectForKey:@"branchIds"])for(id bid in [ch objectForKey:@"branchIds"])[branches addObject:[self intNumber:bid]];NSString *title=[titleInfo objectForKey:@"rus_name"]?:[titleInfo objectForKey:@"_display"]?:[titleInfo objectForKey:@"name"]?:slug;NSMutableDictionary *b=[NSMutableDictionary dictionaryWithObjectsAndKeys:[NSString stringWithFormat:@"%@#%@",slug,chapterID],@"id",slug,@"slug",title,@"titleName",chapterID,@"chapterId",[ch objectForKey:@"volume"]?:[raw objectForKey:@"volume"]?:@"0",@"volume",[ch objectForKey:@"number"]?:[raw objectForKey:@"number"]?:@"0",@"number",[ch objectForKey:@"name"]?:[raw objectForKey:@"chapterName"]?:@"",@"chapterName",branches,@"branchIds",page,@"page",pageCount,@"pageCount",[self isoDate:[self dateStamp:date]],@"date",nil];NSString *cover=[self coverString:[titleInfo objectForKey:@"cover"]?:[raw objectForKey:@"cover"]];if(cover)[b setObject:cover forKey:@"cover"];id site=[titleInfo objectForKey:@"site"]?:[raw objectForKey:@"site"]?:[ch objectForKey:@"site"];if(site)[b setObject:[self intNumber:site] forKey:@"site"];return b;}
+ (NSDictionary *)canonicalDocument:(NSDictionary *)doc {
    NSMutableArray *fav = [NSMutableArray array];
    for (NSDictionary *d in [doc objectForKey:@"favorites"] ?: [NSArray array]) {
        NSString *slug = [self stableKey:d kind:@"favorite"];
        NSDictionary *ref = [NSDictionary dictionaryWithObjectsAndKeys:
                             slug, @"slug",
                             [d objectForKey:@"rus_name"] ?: [d objectForKey:@"_display"] ?: slug, @"name",
                             [self coverString:[d objectForKey:@"cover"]] ?: @"", @"cover",
                             [self intNumber:[d objectForKey:@"site"] ?: @2], @"site",
                             nil];
        [fav addObject:[NSDictionary dictionaryWithObjectsAndKeys:
                        ref, @"ref",
                        [self isoDate:[self stamp:d]], @"date",
                        nil]];
    }

    NSMutableArray *bm = [NSMutableArray array];
    for (NSDictionary *d in [doc objectForKey:@"bookmarks"] ?: [NSArray array]) {
        [bm addObject:[self canonicalBookmark:d recent:NO]];
    }

    NSMutableArray *rec = [NSMutableArray array];
    for (NSDictionary *d in [doc objectForKey:@"recent"] ?: [NSArray array]) {
        if ([d objectForKey:@"_lastChapter"]) {
            [rec addObject:[self canonicalBookmark:d recent:YES]];
        }
    }

    NSMutableDictionary *t = [NSMutableDictionary dictionary];
    NSDictionary *tombstones = [doc objectForKey:@"tombstones"] ?: [NSDictionary dictionary];
    for (NSString *k in tombstones) {
        [t setObject:[self isoDate:[[tombstones objectForKey:k] doubleValue]] forKey:k];
    }

    return [NSDictionary dictionaryWithObjectsAndKeys:
            [NSNumber numberWithInt:1], @"version",
            [self isoDate:[[doc objectForKey:@"updated"] doubleValue]], @"updated",
            bm, @"bookmarks",
            fav, @"favorites",
            rec, @"recent",
            [doc objectForKey:@"read"] ?: [NSDictionary dictionary], @"read",
            t, @"tombstones",
            nil];
}
+ (NSArray *)mergeRows:(NSArray *)a with:(NSArray *)b kind:(NSString *)kind tomb:(NSDictionary *)tomb { NSMutableDictionary *map=[NSMutableDictionary dictionary];for(NSArray *list in [NSArray arrayWithObjects:a?:[NSArray array],b?:[NSArray array],nil])for(NSDictionary *d in list){if(![d isKindOfClass:[NSDictionary class]])continue;NSString *k=[self stableKey:d kind:kind];NSDictionary *old=[map objectForKey:k];if(!old||[self stamp:d]>=[self stamp:old])[map setObject:d forKey:k];}NSMutableArray *out=[NSMutableArray array];for(NSString *k in map){NSDictionary *d=[map objectForKey:k];NSString *prefix=[kind isEqualToString:@"favorite"]?@"f:":([kind isEqualToString:@"recent"]?@"r:":@"b:");NSString *tk=[prefix stringByAppendingString:k];double deleted=[[tomb objectForKey:tk]doubleValue];if(![tomb objectForKey:tk]||deleted<[self stamp:d])[out addObject:d];}return out; }
+ (NSDictionary *)mergeLocal:(NSDictionary *)local remote:(NSDictionary *)remote {
    NSMutableDictionary *t=[NSMutableDictionary dictionaryWithDictionary:[local objectForKey:@"tombstones"]?:[NSDictionary dictionary]];NSDictionary *rt=[remote objectForKey:@"tombstones"];for(NSString *k in rt){if([[rt objectForKey:k]doubleValue]>[[t objectForKey:k]doubleValue])[t setObject:[rt objectForKey:k] forKey:k];}double cutoff=[[NSDate date]timeIntervalSince1970]-90.0*86400.0;NSArray *tombKeys=[[t allKeys]copy];for(NSString *k in tombKeys)if([[t objectForKey:k]doubleValue]<cutoff)[t removeObjectForKey:k];[tombKeys release];
    NSArray *fav=[self mergeRows:[local objectForKey:@"favorites"] with:[remote objectForKey:@"favorites"] kind:@"favorite" tomb:t];NSArray *bm=[self mergeRows:[local objectForKey:@"bookmarks"] with:[remote objectForKey:@"bookmarks"] kind:@"bookmark" tomb:t];NSArray *rec=[self mergeRows:[local objectForKey:@"recent"] with:[remote objectForKey:@"recent"] kind:@"recent" tomb:t];
    NSMutableDictionary *read=[NSMutableDictionary dictionary];for(NSDictionary *doc in [NSArray arrayWithObjects:local,remote,nil]){NSDictionary *r=[doc objectForKey:@"read"];for(NSString *slug in r){NSMutableArray *ids=[NSMutableArray arrayWithArray:[read objectForKey:slug]?:[NSArray array]];for(id x in [r objectForKey:slug])if(![ids containsObject:x])[ids addObject:x];[read setObject:ids forKey:slug];}}
    return [NSDictionary dictionaryWithObjectsAndKeys:[NSNumber numberWithInt:1],@"version",[NSNumber numberWithDouble:[[NSDate date]timeIntervalSince1970]],@"updated",fav,@"favorites",bm,@"bookmarks",rec,@"recent",read,@"read",t,@"tombstones",nil];
}
+ (void)syncWithToken:(NSString *)raw completion:(void (^)(NSString *))completion {
    NSString *token=[self token:raw];if(![token length]){if(completion)completion(@"Введите GitHub token с правом gist");return;}NSString *saved=[[NSUserDefaults standardUserDefaults]objectForKey:@"SLGistID"];NSString *base=@"https://api.github.com";
    void (^finishGist)(NSString *,NSDictionary *)=^(NSString *gid,NSDictionary *remote){NSDictionary *merged=[self mergeLocal:[self localDocument] remote:[self normalizeDocument:remote?:[NSDictionary dictionary]]];[SLStore saveArray:[merged objectForKey:@"favorites"] key:@"SLFavorites"];[SLStore saveArray:[merged objectForKey:@"bookmarks"] key:@"SLBookmarks"];[SLStore saveArray:[merged objectForKey:@"recent"] key:@"SLHistory"];[[NSUserDefaults standardUserDefaults]setObject:[merged objectForKey:@"read"] forKey:@"SLRead"];[[NSUserDefaults standardUserDefaults]setObject:[merged objectForKey:@"tombstones"] forKey:@"SLTombstones"];
        NSDictionary *canonical=[self canonicalDocument:merged];NSDictionary *file=[NSDictionary dictionaryWithObject:[[[NSString alloc]initWithData:[NSJSONSerialization dataWithJSONObject:canonical options:NSJSONWritingPrettyPrinted error:nil] encoding:NSUTF8StringEncoding]autorelease]?:@"{}" forKey:@"content"];NSDictionary *body=[NSDictionary dictionaryWithObjectsAndKeys:@"Slashlib sync — библиотека и прогресс чтения",@"description",[NSNumber numberWithBool:NO],@"public",[NSDictionary dictionaryWithObject:file forKey:@"slashlib-sync.json"],@"files",nil];NSString *url=gid?[NSString stringWithFormat:@"%@/gists/%@",base,gid]:[NSString stringWithFormat:@"%@/gists",base];[self request:gid?@"PATCH":@"POST" url:url token:token body:body completion:^(id obj,NSError *e,NSInteger status){if(e){if(completion)completion([e localizedDescription]);return;}NSString *newID=[obj objectForKey:@"id"]?:gid;if(newID)[[NSUserDefaults standardUserDefaults]setObject:newID forKey:@"SLGistID"];if(completion)completion(@"Синхронизация завершена: данные объединены с GitHub Gist.");}];};
    void (^fetchGist)(NSString *)=^(NSString *gid){[self request:@"GET" url:[NSString stringWithFormat:@"%@/gists/%@",base,gid] token:token body:nil completion:^(id obj,NSError *e,NSInteger status){if(e){if(status==404){[[NSUserDefaults standardUserDefaults]removeObjectForKey:@"SLGistID"];if(completion)completion(@"Сохранённый Gist не найден. Повторите синхронизацию.");}else if(completion)completion([e localizedDescription]);return;}NSDictionary *files=[obj objectForKey:@"files"];NSDictionary *f=[files objectForKey:@"slashlib-sync.json"];NSString *content=[f objectForKey:@"content"];if([content length]&& ![[f objectForKey:@"truncated"]boolValue]){NSData *data=[content dataUsingEncoding:NSUTF8StringEncoding];NSDictionary *remote=[NSJSONSerialization JSONObjectWithData:data options:NSJSONReadingMutableContainers error:nil];if(![remote isKindOfClass:[NSDictionary class]]){if(completion)completion(@"Файл синхронизации повреждён или имеет неизвестный формат; локальные данные не перезаписаны.");return;}finishGist(gid,remote);}else{NSString *rawURL=[f objectForKey:@"raw_url"];if(!rawURL){finishGist(gid,nil);return;}[self request:@"GET" url:rawURL token:token body:nil completion:^(id raw,NSError *err,NSInteger code){if(err){if(completion)completion([err localizedDescription]);return;}if([raw isKindOfClass:[NSDictionary class]])finishGist(gid,raw);else if(completion)completion(@"Не удалось разобрать файл синхронизации; локальные данные не перезаписаны.");}];}}];};
    if([saved length]){fetchGist(saved);return;}
    [self request:@"GET" url:[NSString stringWithFormat:@"%@/gists?per_page=100",base] token:token body:nil completion:^(id obj,NSError *e,NSInteger status){if(e){if(completion)completion([e localizedDescription]);return;}NSString *gid=nil;NSArray *gistList=[obj isKindOfClass:[NSArray class]]?obj:[NSArray array];for(NSDictionary *g in gistList){if([[g objectForKey:@"files"]objectForKey:@"slashlib-sync.json"]){gid=[g objectForKey:@"id"];break;}}if(gid){[[NSUserDefaults standardUserDefaults]setObject:gid forKey:@"SLGistID"];fetchGist(gid);}else finishGist(nil,nil);}];
}
@end
